// The verb hook: answers the work loop's orca.sh verb calls without a model.
//
// The work loop (scripts/work-loop.workflow.js) asks for a verb with
// `agent('', { model: 'orca:{"v":1,"verb":…,"args":[…]}' })`. That request
// reaches `turn.step` before any API call; this hook answers it itself by
// running `bash <this plugin>/scripts/orca.sh <verb> <args…>` and returning
// the result as the agent's text. It never calls `next` for an `orca:` model:
// that would send the request (and the arguments in its model name) to the API.
//
// What it will run, and when:
//   - only an `orca:` request from a subagent (a workflow agent), protocol
//     version 1, whose verb (and subcommand) is one the work loop calls;
//   - only while the session's permission mode is known to be
//     bypassPermissions. The mode is read off the classic hook events that
//     carry it and kept in $.state; no mode seen yet means refuse.
//   - always through bash + orca.sh, never git directly: `$.process.run` runs
//     git with repo hooks off, a script that bash starts does not.
//
// The answer is `b64:` + base64(UTF-8 JSON): `{ v, rc, stdout, stderr }`, or
// `{ v, refused }` when a guard says no, or `{ v, error, timedOut? }` when the
// command could not be run to completion. Encoded whole because the harness
// rewrites subagent results that look instruction-shaped (a verb's output
// naming the session's flags, say); base64 passes untouched.
//
// This hook is the work loop's only way to orca.sh: there is no fallback.
// Where it is not loaded, an `orca:` request goes to the API, which has no
// such model, and the work loop fails loudly at that call (its first is
// `triage claim`), naming the cause.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

export const RELAY_VERSION = 1
export const MODEL_PREFIX = 'orca:'
// The longest `$.process.run` allows. setup's own cap (540 s, verbs/setup.sh)
// sits under it, so a slow worktree setup ends in setup's own soft timeout;
// a verb that still runs past ten minutes fails here, as a timeout naming it.
export const RUN_TIMEOUT_MS = 600_000

// Exactly the verbs work-loop.workflow.js calls through orca(), with the
// subcommands it uses where a verb has several; null means any arguments.
export const ALLOWED: Readonly<Record<string, readonly string[] | null>> = {
  'self-test': null,
  'triage': ['claim', 'release'],
  'spec': ['mark', 'changed'],
  'secrets': ['place', 'remove'],
  'archive': ['attempt'],
  'notes': ['write'],
  'worktree-item': null,
  'provision': null,
  'commit-verify': null,
  'merge-prepare': null,
  'merge-finalize': null,
  'commit-prepare': null,
  'salvage': null,
}

export type RelayRequest = { v: number; verb: string; args: string[] }
export type RelayAnswer =
  | { v: number; rc: number; stdout: string; stderr: string }
  | { v: number; refused: string }
  | { v: number; error: string; timedOut?: true }

const modeAtom = atom({ plugin: 'orca', key: 'permissionMode' } as const, null)

// Parses and checks the request the model name carries. A string answer is
// the refusal reason.
export function parseRequest(model: string): RelayRequest | string {
  if (!model.startsWith(MODEL_PREFIX)) return 'not an orca: request'
  let req: unknown
  try { req = JSON.parse(model.slice(MODEL_PREFIX.length)) } catch { return 'request is not JSON' }
  if (typeof req !== 'object' || req === null || Array.isArray(req)) return 'request is not an object'
  const { v, verb, args } = req as Record<string, unknown>
  if (v !== RELAY_VERSION) return `unknown protocol version ${JSON.stringify(v)} (this hook speaks ${RELAY_VERSION})`
  if (typeof verb !== 'string' || !Object.prototype.hasOwnProperty.call(ALLOWED, verb))
    return `verb ${JSON.stringify(verb)} is not on the work loop's allow-list`
  if (!Array.isArray(args) || args.some(a => typeof a !== 'string')) return 'args must be an array of strings'
  const subcommands = ALLOWED[verb]
  if (subcommands && !subcommands.includes(args[0] as string))
    return `${verb} ${JSON.stringify(args[0] ?? null)} is not on the work loop's allow-list (${subcommands.join(', ')})`
  return { v, verb, args: args as string[] }
}

export function argvFor(root: string, req: RelayRequest): string[] {
  return ['bash', `${root.replace(/\/+$/, '')}/scripts/orca.sh`, req.verb, ...req.args]
}

export function encodeAnswer(answer: RelayAnswer): string {
  const bytes = new TextEncoder().encode(JSON.stringify(answer))
  let bin = ''
  for (let i = 0; i < bytes.length; i += 0x8000)
    bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000))
  return `b64:${btoa(bin)}`
}

// Main-thread events set the mode either way. An event from inside a
// subagent may only close the gate: a subagent's own mode is not the
// session's, and must never be what opens it.
export function nextMode(current: string | null, seen: unknown, fromSubagent: boolean): string | null {
  if (typeof seen !== 'string' || !seen) return current
  if (!fromSubagent) return seen
  return seen === 'bypassPermissions' ? current : seen
}

async function noteMode($: EngineInterface, e: { permission_mode?: string; agent_id?: string }) {
  const current = await read($, modeAtom)
  const mode = nextMode(current, e.permission_mode, e.agent_id !== undefined)
  if (mode !== current) await update($, modeAtom, () => mode)
}

// A rejected $.process.run: the command could not start, or was still
// running at the cap and was killed. The two are told apart by the time it
// took, or by the message (2.1.291 rejects a timeout with "<plugin>:
// $.process.run(<argv0>) aborted: still running after <ms>ms"), so the work
// loop can name a timeout.
export function runFailure(verb: string, message: string, elapsedMs: number): RelayAnswer {
  if (elapsedMs >= RUN_TIMEOUT_MS - 1000 || /still running after|timed? ?out/i.test(message))
    return { v: RELAY_VERSION, error: `orca.sh ${verb} was still running after ${RUN_TIMEOUT_MS / 60_000} minutes, the longest $.process.run allows, and was stopped: ${message}`, timedOut: true }
  return { v: RELAY_VERSION, error: `orca.sh ${verb} did not run to completion: ${message}` }
}

async function answer($: EngineInterface, model: string, agentId: string | undefined): Promise<RelayAnswer> {
  if (!agentId) return { v: RELAY_VERSION, refused: 'orca: requests are answered for workflow agents only' }
  const req = parseRequest(model)
  if (typeof req === 'string') return { v: RELAY_VERSION, refused: req }
  const mode = await read($, modeAtom)
  if (mode !== 'bypassPermissions')
    return { v: RELAY_VERSION, refused: mode === null
      ? 'permission mode not known yet (none seen since this session or hook loaded); orca runs verbs here only in bypassPermissions sessions'
      : `permission mode is ${mode}; orca runs verbs here only in bypassPermissions sessions` }
  let run
  const started = Date.now()
  try { run = await $.process.run(argvFor($.plugin.root, req), { timeoutMs: RUN_TIMEOUT_MS }) }
  catch (err) { return runFailure(req.verb, String((err as Error)?.message ?? err), Date.now() - started) }
  if (run.isStdoutTruncated) return { v: RELAY_VERSION, error: `orca.sh ${req.verb} wrote more than 4 MiB to stdout` }
  return { v: RELAY_VERSION, rc: run.exitCode, stdout: run.stdout, stderr: run.stderr }
}

export const register: Register = on => {
  // The events Phase 3 saw carry permission_mode (2.1.290/291); SubagentStart
  // and SessionStart do not.
  on('classic.UserPromptSubmit', async ($, e, next) => {
    try { await noteMode($, e) } catch { /* the gate stays as it was */ }
    return next(e)
  }).catch(($, e, next) => next(e))
  on('classic.PostToolUse', async ($, e, next) => {
    try { await noteMode($, e) } catch { /* the gate stays as it was */ }
    return next(e)
  }).catch(($, e, next) => next(e))
  on('classic.SubagentStop', async ($, e, next) => {
    try { await noteMode($, e) } catch { /* the gate stays as it was */ }
    return next(e)
  }).catch(($, e, next) => next(e))
  on('classic.Stop', async ($, e, next) => {
    try { await noteMode($, e) } catch { /* the gate stays as it was */ }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.step', async function* ($, e, next) {
    if (!e.model.startsWith(MODEL_PREFIX)) return yield* next(e)
    let reply: RelayAnswer
    try { reply = await answer($, e.model, e.agentId) }
    catch (err) { reply = { v: RELAY_VERSION, error: `orca hook failed: ${String((err as Error)?.message ?? err)}` } }
    const text = encodeAnswer(reply)
    yield { kind: 'text', index: 0, text }
    yield { kind: 'stop', stopReason: 'end_turn', usage: null }
    return { turnId: e.turnId, index: e.index, answer: text, toolUses: [], stopReason: 'end_turn', usage: null }
  }).catch(async function* ($, e, next) {
    // An orca: request never goes to the API, even when this hook failed.
    if (next.called || !e.model.startsWith(MODEL_PREFIX)) return yield* next(e)
    const text = encodeAnswer({ v: RELAY_VERSION, error: `orca hook failed: ${next.error.message ?? next.error.kind}` })
    yield { kind: 'text', index: 0, text }
    yield { kind: 'stop', stopReason: 'end_turn', usage: null }
    return { turnId: e.turnId, index: e.index, answer: text, toolUses: [], stopReason: 'end_turn', usage: null }
  })
}

files.hooks/run-band.tsx:
// The run band: a live view of the orca run this session launched, drawn
// above the prompt. A read-only observer — it watches this session's own
// Workflow launches of spec.workflow.js / work-loop.workflow.js, then reads
// the run directory and the workflow's journal on a short tick while that run
// is tracked. It writes nothing anywhere but its own $.state, and draws
// nothing where the AbovePrompt band is not raised (VS Code, `claude -p`).
//
// The derivation itself is pure and lives in ./derive.ts.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'

import type { OrcaBand, OrcaRun, OrcaTone } from '../types'
import { derive, headerRule, itemsFromArgs, layoutRows, parseTaskNotifications, projectDirName, slugOf } from './derive'
import type { JournalRead, RuleTone, RunFiles } from './derive'

const runAtom = atom({ plugin: 'orca', key: 'run' } as const, null)
const bandAtom = atom({ plugin: 'orca', key: 'band' } as const, null)

const TICK_MS = 1500
// $.fs.read refuses anything larger.
const MAX_READ = 4 * 1024 * 1024
// A spec that finished and then sat through this many of the person's own
// prompts with no work-loop launch was abandoned at the checkpoint.
const SPEC_IDLE_PROMPTS = 3

// Module variables start over on a hot reload; the run itself is in $.state.
// A timer keeps the `$` of the hook that started it, which stays usable after
// that dispatch ends (checked under `claude -p` on 2.1.290).
let ticker: Timer | null = null
let ticking = false
const textCache = new Map<string, { size: number; mtimeMs: number; text: string }>()

function kindOf(scriptPath: unknown): OrcaRun['kind'] | null {
  if (typeof scriptPath !== 'string') return null
  if (/(^|\/)spec\.workflow\.js$/.test(scriptPath)) return 'spec'
  if (/(^|\/)work-loop\.workflow\.js$/.test(scriptPath)) return 'build'
  return null
}

function record(v: unknown): Record<string, unknown> | null {
  if (typeof v === 'string') { try { v = JSON.parse(v) } catch { return null } }
  return typeof v === 'object' && v !== null && !Array.isArray(v) ? (v as Record<string, unknown>) : null
}

// Reads a file through a size+mtime cache: an unchanged journal is not read
// again every tick. 'too-large' past what $.fs.read takes.
async function readCached($: EngineInterface, path: string): Promise<JournalRead> {
  let stat
  try { stat = await $.fs.stat(path) } catch { return { status: 'missing' } }
  if (stat.size > MAX_READ) return { status: 'too-large' }
  const hit = textCache.get(path)
  if (hit && hit.size === stat.size && hit.mtimeMs === stat.mtimeMs) return { status: 'ok', text: hit.text }
  try {
    const text = await $.fs.read(path)
    textCache.set(path, { size: stat.size, mtimeMs: stat.mtimeMs, text })
    return { status: 'ok', text }
  } catch { return { status: 'unreadable' } }
}

async function listNames($: EngineInterface, dir: string): Promise<{ name: string; mtimeMs: number }[]> {
  try { return (await $.fs.list(dir)).map(f => ({ name: f.name, mtimeMs: f.mtimeMs })) } catch { return [] }
}

async function readRunFiles($: EngineInterface, run: OrcaRun): Promise<RunFiles> {
  const files: RunFiles = { runDirExists: true, spec: null, reviews: [], plans: [], merged: null, reportMtimeMs: null, agents: [] }
  let entries
  try { entries = await $.fs.list(run.runDir) } catch {
    files.runDirExists = await $.fs.exists(run.runDir).catch(() => true)
    return files
  }
  const named = new Map(entries.map(f => [f.name, f]))
  const report = named.get('report.md')
  files.reportMtimeMs = report ? report.mtimeMs : null
  if (run.amendPath) {
    const st = await $.fs.stat(run.amendPath).catch(() => null)
    files.spec = st ? { mtimeMs: st.mtimeMs, text: null } : null
  } else {
    const spec = named.get('spec.md')
    // spec.md's text is needed only when the launch's own item list was unreadable.
    const needText = run.kind === 'build' && run.items.length === 0
    const text = spec && needText ? await readCached($, `${run.runDir}/spec.md`) : null
    files.spec = spec ? { mtimeMs: spec.mtimeMs, text: text && text.status === 'ok' ? text.text : null } : null
  }
  if (named.has('reviews')) files.reviews = await listNames($, `${run.runDir}/reviews`)
  if (named.has('plans')) files.plans = (await listNames($, `${run.runDir}/plans`)).map(f => f.name)
  if (run.kind === 'build' && named.has('merged.tsv')) {
    const merged = await readCached($, `${run.runDir}/merged.tsv`)
    files.merged = merged.status === 'ok' ? merged.text : null
  }
  if (run.kind === 'spec' && run.journal) files.agents = await listNames($, run.journal.replace(/\/[^/]*$/, ''))
  return files
}

// Writes only a change: every write redraws the band.
async function setBand($: EngineInterface, band: OrcaBand | null) {
  if (JSON.stringify(await read($, bandAtom)) === JSON.stringify(band)) return
  await update($, bandAtom, () => band)
}

async function forget($: EngineInterface) {
  if (ticker) ticker.cancel()
  ticker = null
  await update($, runAtom, () => null)
  await setBand($, null)
}

async function tick($: EngineInterface) {
  if (ticking) return
  ticking = true
  try {
    const run = await read($, runAtom)
    if (!run) {
      if (ticker) ticker.cancel()
      ticker = null
      await setBand($, null)
      return
    }
    // Nothing draws the band here (a `claude -p` run, VS Code): read nothing.
    const surfaces = await $.session.surfaces()
    if (!surfaces.some(s => s === 'terminal' || s === 'desktop')) return
    const files = await readRunFiles($, run)
    const journal: JournalRead = run.journal ? await readCached($, run.journal) : { status: 'missing' }
    const out = derive(run, files, journal, await $.clock.now())
    // The run may have ended (a notification) or been replaced (a new launch)
    // while this tick read files; a stale answer must not redraw the band.
    if ((await read($, runAtom))?.runId !== run.runId) return
    if (out.finished) await forget($)
    else await setBand($, out.band)
  } catch {
    // Never crash the session over a status line; the next tick tries again.
  } finally {
    ticking = false
  }
}

function follow($: EngineInterface) {
  if (!ticker) ticker = $.clock.every(TICK_MS, () => { void tick($) })
  void tick($)
}

// The launch result names the workflow's transcript directory, which holds
// journal.jsonl. Without it, the same path is rebuilt from the session.
async function journalPath($: EngineInterface, transcriptDir: unknown, runId: string): Promise<string | null> {
  if (typeof transcriptDir === 'string' && transcriptDir) return `${transcriptDir.replace(/\/+$/, '')}/journal.jsonl`
  const config = (await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${(await $.env.get('HOME')) ?? ''}/.claude`
  if (!config.startsWith('/')) return null
  const cwd = await $.session.cwd()
  const session = await $.session.id()
  return `${config}/projects/${projectDirName(cwd)}/${session}/subagents/workflows/${runId}/journal.jsonl`
}

async function track($: EngineInterface, kind: OrcaRun['kind'], input: Record<string, unknown>, launched: unknown, since: number) {
  const result = record(launched)
  if (!result || result.status !== 'async_launched') return
  const runId = result.runId
  const taskId = result.taskId
  if (typeof runId !== 'string' || typeof taskId !== 'string') return
  const args = record(input.args)
  const runDir = args && typeof args.runDir === 'string' ? args.runDir.replace(/\/+$/, '') : null
  if (!args || !runDir) return
  const run: OrcaRun = {
    kind,
    runDir,
    slug: typeof args.slug === 'string' && args.slug ? args.slug : slugOf(runDir),
    runId,
    taskId,
    journal: await journalPath($, result.transcriptDir, runId),
    since,
    items: kind === 'build' ? itemsFromArgs(args) : [],
    amendPath: kind === 'spec' && typeof args.amendPath === 'string' ? args.amendPath : null,
    reviewer: kind === 'spec' && typeof args.reviewer === 'string' && args.reviewer ? args.reviewer : null,
    specEnded: false,
    idlePrompts: 0,
  }
  await update($, runAtom, () => run)
  follow($)
}

async function onPrompt($: EngineInterface, origin: string, text: string) {
  const run = await read($, runAtom)
  if (!run) return
  if (origin === 'task-notification') {
    const ended = parseTaskNotifications(text).find(n => n.taskId === run.taskId)
    if (!ended) return
    // The work loop ending ends the run's live phase. A spec that completed
    // stays on screen as ready (the checkpoint, or the launch about to come);
    // one that failed or was stopped does not.
    if (run.kind === 'build' || ended.status !== 'completed') await forget($)
    else await update($, runAtom, r => (r ? { ...r, specEnded: true } : r))
    return
  }
  if ((origin === 'composer' || origin === 'bridge') && run.kind === 'spec') {
    const band = await read($, bandAtom)
    if (!run.specEnded && band?.detail !== 'ready') return
    if (run.idlePrompts + 1 >= SPEC_IDLE_PROMPTS) await forget($)
    else await update($, runAtom, r => (r ? { ...r, idlePrompts: r.idlePrompts + 1 } : r))
  }
}

type Style = { color?: string; dimColor?: boolean; bold?: boolean }

const TONE: Record<OrcaTone, Style> = {
  done: { color: 'success' },
  live: { color: 'suggestion' },
  wait: { dimColor: true },
  queued: { dimColor: true },
  blocked: { color: 'error' },
  cut: { dimColor: true },
}

// The top border: the rule and the name in Claude's accent, the facts set in it.
const RULE: Record<RuleTone, Style> = {
  rule: { color: 'claude', dimColor: true },
  name: { color: 'claude', bold: true },
  slug: { bold: true },
  phase: { color: 'suggestion' },
  detail: {},
  sep: { dimColor: true },
  note: { color: 'warning' },
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    // A hot reload drops the timer; the tracked run is still in $.state.
    if (await read($, runAtom)) follow($)
    return next(e)
  })

  on('tool.call', { tool: 'Workflow' }, async ($, e, next) => {
    // Only the main conversation's own launches: the skills launch from there.
    if (e.tool !== 'Workflow' || e.agentId !== undefined) return next(e)
    const kind = kindOf(e.scriptPath)
    if (!kind) return next(e)
    const since = await $.clock.now()
    const ran = await next(e)
    if (!ran.isError && 'result' in ran) {
      try { await track($, kind, { args: e.args }, ran.result, since) } catch { /* observe only */ }
    }
    return ran
  }).catch(($, e, next) => next(e)) // an observer never stands in a call's way

  on('prompt.submit', async ($, e, next) => {
    try { await onPrompt($, e.origin.kind, e.text) } catch { /* observe only */ }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('session.end', async ($, e, next) => {
    try { await forget($) } catch { /* observe only */ }
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const band = await read($, bandAtom)
    if (!band || !(await read($, runAtom))) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    const columns = Math.max(24, e.props.bodyColumns || 80)

    // A blank row above the rule sets the band off from the transcript's last
    // line, and one below it sets the rule off from the rows.
    return (
      <Box flexDirection="column" marginTop={1}>
        <Box marginBottom={band.rows.length ? 1 : 0}>
          {headerRule(band, columns).map(piece => (
            <Text {...RULE[piece.tone]} wrap="truncate-end">{piece.text}</Text>
          ))}
        </Box>
        {layoutRows(band.rows, columns).map(line => (
          <Box>
            <Text>{'  '}</Text>
            <Text bold>{line.id}</Text>
            <Text>{`  ${line.title}  `}</Text>
            <Text {...TONE[line.row.tone]} wrap="truncate-end">{line.tail}</Text>
          </Box>
        ))}
      </Box>
    )
  })
}

